/**
 * Seiton i18n（spec: 決定39・46 — 多言語対応・Obsidianの言語設定に追従）
 * 初期対応: 日本語 / 英語 / 中国語 / 韓国語 / スペイン語 / ポルトガル語 / フランス語 / ドイツ語
 * フォルダ名・ファイル名は英語固定（言語中立）で、UI表示のみ多言語。
 */

