const withEnglishFallback = (dict: Dict): Dict => ({ ...en, ...dict });

export const LOCALES: Record<Lang, Dict> = {
  de: withEnglishFallback(de),
  en: withEnglishFallback(en),
  es: withEnglishFallback(es),
  fr: withEnglishFallback(fr),
  ja: withEnglishFallback(ja),
  ko: withEnglishFallback(ko),
  "pt-BR": withEnglishFallback(ptBR),
  "zh-CN": withEnglishFallback(zhCN),
};

/** Obsidianの言語設定（moment.locale）から言語を判定・非対応なら英語 */
export function detectLang(locale: string): Lang {
  const l = locale.toLowerCase();
  if (l.startsWith("ja")) {
    return "ja";
  }
  if (l.startsWith("zh")) {
    return "zh-CN";
  }
  if (l.startsWith("ko")) {
    return "ko";
  }
  if (l.startsWith("es")) {
    return "es";
  }
  if (l.startsWith("pt")) {
    return "pt-BR";
  }
  if (l.startsWith("fr")) {
    return "fr";
  }
  if (l.startsWith("de")) {
    return "de";
  }
  return "en";
}

/** 翻訳取得。{name} 形式のプレースホルダを置換 */
export function t(
  lang: Lang,
  key: MessageKey,
  params?: Record<string, string>
): string {
  let s = LOCALES[lang][key] ?? LOCALES.en[key] ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      s = s.split(`{{${k}}}`).join(v).split(`{${k}}`).join(v);
    }
  }
  return s;
}

/** すべての言語で同じキーセットを持つことの検証用 */
export function assertCompleteDictionaries(): string[] {
  const keys = Object.keys(ja) as MessageKey[];
  const missing: string[] = [];
  for (const lang of LANGS) {
    for (const key of keys) {
      if (!(key in LOCALES[lang])) {
        missing.push(`${lang}:${key}`);
      }
    }
  }
  return missing;
}
